// Ollama returns the PromQL in `response`; strip markdown/backticks/labels and
// keep the first non-empty line so the Prometheus query node gets a bare query.
let q = String(($json.response || '')).trim();
q = q.replace(/```[a-zA-Z]*/g, '').replace(/`/g, '').trim();
q = q.split('\n').map(s => s.trim()).filter(Boolean)[0] || 'up';
q = q.replace(/^(promql|query)\s*[:=]\s*/i, '').trim();
const question = $('Home question').item.json.body ? ($('Home question').item.json.body.question || '') : '';
return [{ json: { promql: q, question } }];

// Build the phrasing prompt from the question + the Prometheus result. Handle the
// empty-result case deterministically: an empty `up == 0` / ALERTS query means all
// healthy (good news), which is different from a missing sensor value.
const q = $('Extract PromQL').item.json.question || '';
const promql = $('Extract PromQL').item.json.promql || '';
const result = ($json.data && $json.data.result) ? $json.data.result : [];
let rows;
if (result.length === 0) {
  rows = /\bup\b|ALERTS/i.test(promql)
    ? 'RESULT: nothing matched — every monitored service is up and no alerts are firing.'
    : 'RESULT: no data — that sensor was not found.';
} else {
  rows = result.map(r => {
    const m = r.metric || {};
    const name = m.friendly_name || m.instance || m.alertname || m.job || JSON.stringify(m);
    const val = Array.isArray(r.value) ? r.value[1] : '';
    return `${name} = ${val}`;
  }).slice(0, 25).join('\n');
}
const prompt = [
  'You are a home assistant. Answer the question in ONE short, friendly sentence based only on RESULT.',
  'If RESULT says every service is up, reassure that everything is healthy.',
  'Do not mention PromQL or metric names.',
  '',
  `Question: ${q}`,
  rows,
].join('\n');
return [{ json: { prompt, question: q, promql, rows } }];

// Final node: webhook responseMode=lastNode returns this JSON to the caller.
const answer = String(($json.response || '')).trim() || 'Sorry, I could not work that out.';
return [{ json: { answer, promql: $('Build answer prompt').item.json.promql, data: $('Build answer prompt').item.json.rows } }];
